     "mota": "kutxa",
     "kolorea": "laranja",
     "titulua": null,
     "blokeak": [
      {
       "mota": "testua",
       "html": "<math display=\"block\"><mrow><msubsup><mo>∫</mo><mn>0</mn><mn>1</mn></msubsup><mfrac><mrow><mi>d</mi><mi>t</mi></mrow><msup><mi>t</mi><mi>p</mi></msup></mfrac><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> konbergentea da </mtext><mspace width=\"0.333em\"></mspace></mrow><mo>⇔</mo><mi>p</mi><mo>&lt;</mo><mn>1</mn><mo>,</mo><mspace width=\"1.0em\"></mspace><mrow><mspace width=\"0.333em\"></mspace><mtext mathvariant=\"normal\"> balioa </mtext><mspace width=\"0.333em\"></mspace></mrow><mfrac><mn>1</mn><mrow><mn>1</mn><mo>−</mo><mi>p</mi></mrow></mfrac><mi>.</mi></mrow></math>"
      }
     ]
